{
  "name": "omgvibe",
  "version": "0.2.7",
  "description": "Interactive NPX wizard for configuring CodeX, Claude Code, OpenCode, or CodeWhale for OhMyGPT API access.",
  "type": "commonjs",
  "main": "dist/index.js",
  "bin": {
    "omgvibe": "dist/index.js"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsc",
    "postbuild": "node -e \"require('fs').chmodSync('dist/index.js', 0o755)\"",
    "clean": "rimraf dist",
    "lint": "tsc --noEmit",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "codex",
    "claude",
    "opencode",
    "codewhale",
    "cli",
    "omg",
    "ohmygpt"
  ],
  "author": "DogeNet LLC",
  "license": "MIT",
  "dependencies": {
    "kleur": "^4.1.5",
    "prompts": "^2.4.2"
  },
  "devDependencies": {
    "@types/node": "^24.5.0",
    "@types/prompts": "^2.4.9",
    "rimraf": "^6.1.3",
    "typescript": "^5.9.2"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DogeNet-LLC/omgvibe.git"
  },
  "bugs": {
    "url": "https://github.com/DogeNet-LLC/omgvibe/issues"
  },
  "homepage": "https://github.com/DogeNet-LLC/omgvibe#readme"
}
